import { Avatar, AvatarFallback } from "./ui/avatar";
import { Badge } from "./ui/badge";
import { AccountMenu } from "./AccountMenu";
import { DictionaryModal } from "./DictionaryModal";

export function ChatHeader({
    title = "AI Assistant",
    subtitle = "Always here to help",
    isOnline = true,
    isLoggedIn = false,
    userName,
    onLogin = () => { },
    onLogout = () => { },
    onRegister = () => { },
    onWordLookup
}) {
    return (
        <div className="flex items-center gap-3 p-4 border-b bg-gradient-to-r from-slate-700 via-blue-600 to-slate-600 text-white">
            <Avatar className="w-10 h-10">
                <AvatarFallback className="bg-gradient-to-r from-blue-400 to-slate-500 text-white">
                    AI
                </AvatarFallback>
            </Avatar>

            <div className="flex-1">
                <div className="flex items-center gap-2">
                    <h2 className="font-medium text-white">{title}</h2>
                    <Badge
                        variant={isOnline ? "default" : "secondary"}
                        className={`text-xs ${isOnline
                            ? "bg-blue-500 hover:bg-blue-600 text-white"
                            : "bg-gray-500 hover:bg-gray-600 text-white"
                            }`}
                    >
                        {isOnline ? "Online" : "Offline"}
                    </Badge>
                </div>
                <p className="text-sm text-slate-100">{subtitle}</p>
            </div>

            <div className="flex items-center gap-2">
                <DictionaryModal onWordLookup={onWordLookup} />
                <AccountMenu
                    isLoggedIn={isLoggedIn}
                    userName={userName}
                    onLogin={onLogin}
                    onLogout={onLogout}
                    onRegister={onRegister}
                />
            </div>
        </div>
    );
}
